package com.nigson.experience.files;

import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import tools.jackson.databind.JsonNode;import io.micrometer.core.instrument.MeterRegistry;import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;
/** Owner-local file commands: persist intent, release transaction for storage, then persist verified result. */
public final class ExperienceFileService {
 private final FileRepository files;private final FileStorage storage;private final PlatformStore store;private final AuditWriter audit;private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final Clock clock;private final String env;private final MeterRegistry metrics;private final boolean scanEnabled;
 public ExperienceFileService(FileRepository f,FileStorage s,PlatformStore p,AuditWriter a,JdbcTemplate j,PlatformTransactionManager m,Clock c,String e,MeterRegistry metrics,boolean scanEnabled){files=f;storage=s;store=p;audit=a;jdbc=j;tx=new TransactionTemplate(m);tx.setTimeout(3);clock=c;env=e;this.metrics=metrics;this.scanEnabled=scanEnabled;}
 private static Problem.Failure rule(){return FileValues.rule();}private void configured(){if(!storage.configured())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
 private static String subject(ActorAssertion.Actor a){return a.party().toString();}private static String actor(PrivateWorkload.Proof p,String api){if(p==null||p.actor()==null||!p.client().equals("nigson-commerce")||!p.route().api().equals(api)||!p.route().owner().equals("experience")||!p.route().scope().equals(scope(api))||!p.actor().scopes().contains(scope(api))||p.actor().organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p.actor().roles().contains("CUSTOMER")?"CUSTOMER":"CONTENT_EDITOR";}
 private static String scope(String api){return switch(api){case "API-114"->"files.upload_WITH_SIGNED_ACTOR";case "API-115"->"files.complete_WITH_SIGNED_ACTOR";case "API-116"->"files.download_WITH_SIGNED_ACTOR";default->throw new IllegalArgumentException("API_SCOPE_INVALID");};}
 private static void purposeRole(ActorAssertion.Actor a,FileValues.Upload in){if(in.purpose().equals("DISTRIBUTOR_PROOF")){if(!a.roles().contains("CUSTOMER")||a.organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}else if(!a.roles().contains("CONTENT_EDITOR"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private void access(ActorAssertion.Actor a,FileRepository.Stored f){if(a.organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(f.purpose().equals("DISTRIBUTOR_PROOF")){if(!a.roles().contains("CUSTOMER")||!a.party().equals(f.owner()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(f.classification().equals("PUBLIC"))throw rule();return;}if(a.party().equals(f.owner()))return;if(!a.roles().contains("CONTENT_EDITOR")||f.linkedResourceId()==null||!"CONTENT_ITEM".equals(f.linkedResourceType())||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.content_item i JOIN experience.content_revision r ON r.id=i.current_published_revision_id WHERE i.id=? AND i.status='ACTIVE' AND r.state='PUBLISHED' AND r.body::text LIKE ?)",Boolean.class,f.linkedResourceId(),"%"+f.id()+"%")))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private FileValues.Asset dto(FileRepository.Stored f){return new FileValues.Asset(f.id(),f.status(),f.purpose(),f.mime(),f.size(),f.checksum(),null,f.version());}
 private static JsonNode canonical(UUID id,long version,JsonNode body){return EventCodec.JSON.valueToTree(Map.of("assetId",id,"version",version,"body",body));}
 private void audit(String actor,AuditValues.ActorKind kind,AuditValues.Action action,FileRepository.Stored before,FileRepository.Stored after,UUID corr){audit.append(actor,kind,action,AuditValues.Resource.FILE,after.id(),corr,kind==AuditValues.ActorKind.USER?AuditValues.Reason.OPERATOR_REQUEST:AuditValues.Reason.VERIFIED_PROVIDER,before==null?null:Map.of("state",before.status(),"version",before.version()),Map.of("state",after.status(),"version",after.version()),null);}
 private void verify(FileRepository.Stored f,FileStorage.ObjectInfo info,String owner){if(info==null||info.size()!=f.size()||!Objects.equals(info.mimeType(),f.mime())||!Objects.equals(info.checksum(),f.checksum())||!Objects.equals(info.owner(),owner)||!info.encrypted()||info.version()==null||info.etag()==null)throw rule();}
 public FileValues.UploadResult upload(PrivateWorkload.Proof proof,JsonNode body,String key,UUID corr){ActorAssertion.Actor a=proof==null?null:proof.actor();actor(proof,"API-114");purposeRole(a,FileValues.upload(body));if(corr==null||key==null)throw ApiValues.invalid();ApiValues.idempotencyKey(key);configured();var in=FileValues.upload(body);if(in.linkedResourceId()!=null){boolean ownedResource=in.purpose().equals("DISTRIBUTOR_PROOF")?Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.distributor_application WHERE id=? AND party_id=?)",Boolean.class,in.linkedResourceId(),a.party())):Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.content_item WHERE id=? AND status='ACTIVE')",Boolean.class,in.linkedResourceId()));if(!ownedResource)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}String principal=subject(a);var request=EventCodec.JSON.valueToTree(in);var replay=store.replayLocal(principal,"API-114",key,request);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),FileValues.UploadResult.class);UUID id=EventCodec.uuid7(clock.instant());String source=FileValues.key(env,in.purpose(),id,0,in.extension()),target=FileValues.key(env,in.purpose(),id,1,in.extension());Instant expiry=clock.instant().plusSeconds(300);var prep=store.executeLocal(principal,"API-114-PREPARE",key,request,db->{var f=files.create(id,a.party(),a.organization(),in,source,target,expiry,principal);audit(principal,AuditValues.ActorKind.USER,AuditValues.Action.FILE_UPLOAD,null,f,corr);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(Map.of("id",id,"key",source,"expiry",expiry)),id);});UUID asset=prep.resource();var f=files.find(asset,false);access(a,f);var signed=storage.upload(asset,f.sourceKey(),in,principal,clock.instant());var done=store.executeLocal(principal,"API-114",key,request,db->new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new FileValues.UploadResult(asset,signed.url(),signed.headers(),signed.expiresAt())),asset));return EventCodec.JSON.treeToValue(done.body(),FileValues.UploadResult.class);}
 public FileValues.Asset complete(PrivateWorkload.Proof proof,UUID id,long expected,JsonNode body,String key,UUID corr){ActorAssertion.Actor a=proof==null?null:proof.actor();actor(proof,"API-115");if(corr==null||expected<0)throw ApiValues.invalid();ApiValues.idempotencyKey(key);configured();String checksum=FileValues.completion(body),principal=subject(a);var before=files.find(id,false);access(a,before);if(!a.party().equals(before.owner())||!checksum.equals(before.checksum()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);JsonNode req=canonical(id,expected,body);var replay=store.replayLocal(principal,"API-115",key,req);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),FileValues.Asset.class);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!before.status().equals("UPLOADING")||!before.uploadExpires().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  var info=storage.quarantine(before.sourceKey());verify(before,info,principal);
  var result=store.executeLocal(principal,"API-115",key,req,db->{var current=files.find(id,true);access(a,current);if(current.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!current.status().equals("UPLOADING"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);verify(current,info,principal);UUID command=EventCodec.uuid7(clock.instant());var after=files.quarantined(current,info,command,principal);var event=new LinkedHashMap<String,Object>();event.put("event_id",command);event.put("event_type","file.scan.requested.v1");event.put("schema_version",1);event.put("producer","experience");event.put("occurred_at",clock.instant().toString());event.put("aggregate_id",id);event.put("aggregate_version",after.version());event.put("organization_id",null);event.put("correlation_id",corr);event.put("traceparent",null);event.put("payload",Map.of("owner_service","experience","asset_id",id,"checksum_sha256",checksum));store.append(EventCodec.JSON.writeValueAsString(event),principal);audit(principal,AuditValues.ActorKind.USER,AuditValues.Action.FILE_COMPLETION,current,after,corr);return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(dto(after)),id);});return EventCodec.JSON.treeToValue(result.body(),FileValues.Asset.class);}
 private static String scanner(PrivateWorkload.Proof p){var r=PrivateWorkload.ROUTES.stream().filter(x->x.api().equals("API-136")&&x.owner().equals("experience")&&x.client().equals("nigson-integration")).findFirst().orElseThrow();if(p==null||!r.equals(p.route())||!r.scope().equals("files.scan.write")||p.actor()!=null||p.subject()==null||p.subject().isBlank())throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return "scanner:"+p.client();}
 public FileValues.Asset scan(PrivateWorkload.Proof proof,UUID id,long expected,JsonNode body,String key,UUID corr){String principal=scanner(proof);configured();if(!scanEnabled)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(expected<0||key==null)throw ApiValues.invalid();var input=FileValues.scan(body);if(!key.equals(input.commandId().toString()))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var initial=files.find(id,false);if(initial.scanCommand()==null||!initial.scanCommand().equals(input.commandId())||!initial.checksum().equals(input.checksumSha256()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);JsonNode req=canonical(id,expected,body);String hash=EventCodec.hash(body);var replay=store.replayLocal(principal,"API-136",key,req);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),FileValues.Asset.class);
  FileRepository.Stored prepared=tx.execute(s->{var cur=files.find(id,true);if(cur.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(cur.scanCommand()==null||!cur.scanCommand().equals(input.commandId())||!cur.checksum().equals(input.checksumSha256()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(Set.of("CLEAN","REJECTED").contains(cur.status())){if(!Objects.equals(cur.scanHash(),hash))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return cur;}if(!cur.status().equals("QUARANTINED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(cur.transferState().equals("COPYING")){if(cur.lease()!=null&&cur.lease().isAfter(clock.instant()))throw new PlatformStore.Conflict("IDEMPOTENCY_IN_PROGRESS");return files.unknown(cur,hash,principal);}if(cur.transferState().equals("UNKNOWN")){if(!Objects.equals(cur.scanHash(),hash))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return cur;}var claimed=files.claim(cur,input,hash,clock.instant().plusSeconds(15),principal);audit(principal,AuditValues.ActorKind.SERVICE,AuditValues.Action.FILE_PROMOTION_REQUEST,cur,claimed,corr);return claimed;});
  if(input.result().equals("REJECTED")){var out=store.executeLocal(principal,"API-136",key,req,db->{var cur=files.find(id,true);if(cur.status().equals("REJECTED"))return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(dto(cur)),id);var after=files.finish(cur,"REJECTED",hash,input.scannerVersion(),principal);audit(principal,AuditValues.ActorKind.SERVICE,AuditValues.Action.FILE_SCAN_RESULT,cur,after,corr);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(dto(after)),id);});return EventCodec.JSON.treeToValue(out.body(),FileValues.Asset.class);}
  try{if(prepared.transferState().equals("UNKNOWN")){var finalInfo=storage.finalObject(prepared.finalKey(),prepared.classification().equals("PRIVATE"));if(finalInfo!=null)verify(prepared,finalInfo,prepared.owner().toString());else{var source=storage.quarantine(prepared.sourceKey());verify(prepared,source,prepared.owner().toString());if(!Objects.equals(source.version(),prepared.sourceVersion())||!Objects.equals(source.etag(),prepared.sourceEtag()))throw rule();prepared=tx.execute(status->{var current=files.find(id,true);if(!current.transferState().equals("UNKNOWN")||!Objects.equals(current.scanHash(),hash))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return files.claim(current,input,hash,clock.instant().plusSeconds(15),principal);});storage.promote(prepared.sourceKey(),prepared.sourceVersion(),prepared.sourceEtag(),prepared.finalKey(),prepared.classification().equals("PRIVATE"));verify(prepared,storage.finalObject(prepared.finalKey(),prepared.classification().equals("PRIVATE")),prepared.owner().toString());}}else{storage.promote(prepared.sourceKey(),prepared.sourceVersion(),prepared.sourceEtag(),prepared.finalKey(),prepared.classification().equals("PRIVATE"));verify(prepared,storage.finalObject(prepared.finalKey(),prepared.classification().equals("PRIVATE")),prepared.owner().toString());}}catch(RuntimeException uncertain){tx.executeWithoutResult(s->{var current=files.find(id,true);files.unknown(current,hash,principal);audit.append(principal,AuditValues.ActorKind.SERVICE,AuditValues.Action.FILE_TRANSFER_UNKNOWN,AuditValues.Resource.FILE,id,corr,AuditValues.Reason.RECONCILIATION,null,Map.of("state","UNKNOWN"),null);});metrics.counter("nigson.experience.files.transfer","outcome","UNKNOWN").increment();throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
  var out=store.executeLocal(principal,"API-136",key,req,db->{var cur=files.find(id,true);if(cur.status().equals("CLEAN"))return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(dto(cur)),id);if(!cur.transferState().equals("COPYING")&&!cur.transferState().equals("UNKNOWN"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var after=files.finish(cur,"CLEAN",hash,input.scannerVersion(),principal);audit(principal,AuditValues.ActorKind.SERVICE,AuditValues.Action.FILE_SCAN_RESULT,cur,after,corr);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(dto(after)),id);});metrics.counter("nigson.experience.files.scan","outcome",input.result()).increment();return EventCodec.JSON.treeToValue(out.body(),FileValues.Asset.class);}
 public FileValues.Download download(PrivateWorkload.Proof proof,UUID id,UUID corr){ActorAssertion.Actor a=proof==null?null:proof.actor();actor(proof,"API-116");if(corr==null)throw ApiValues.invalid();configured();var f=files.find(id,false);access(a,f);if(!Set.of("CLEAN").contains(f.status()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);tx.executeWithoutResult(s->{var current=files.find(id,true);access(a,current);if(!current.status().equals("CLEAN"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);audit(subject(a),AuditValues.ActorKind.USER,AuditValues.Action.PRIVATE_FILE_DOWNLOAD,current,current,corr);});var signed=storage.download(f.key(),f.classification().equals("PRIVATE"),clock.instant());return new FileValues.Download(signed.url(),signed.expiresAt());}
}
